```go
package logfilter

import (
	"bufio"
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"strings"
)

var levelRank = map[string]int{
	"debug": 10,
	"info":  20,
	"warn":  30,
	"error": 40,
	"fatal": 50,
}

type logHeader struct {
	Level string `json:"level"`
}

func FilterJSONLLogs(r io.Reader, w io.Writer, minLevel string) (int, error) {
	threshold, ok := levelRank[strings.ToLower(strings.TrimSpace(minLevel))]
	if !ok {
		return 0, fmt.Errorf("unknown minLevel: %q", minLevel)
	}

	scanner := bufio.NewScanner(r)
	scanner.Buffer(make([]byte, 64*1024), 1024*1024)
	bufw := bufio.NewWriter(w)
	written := 0

	for scanner.Scan() {
		line := bytes.TrimSpace(scanner.Bytes())
		if len(line) == 0 {
			continue
		}
		var hdr logHeader
		if err := json.Unmarshal(line, &hdr); err != nil {
			return written, fmt.Errorf("malformed jsonl line: %w", err)
		}
		if levelRank[strings.ToLower(hdr.Level)] >= threshold {
			if _, err := bufw.Write(line); err != nil {
				return written, err
			}
			if err := bufw.WriteByte('\n'); err != nil {
				return written, err
			}
			written++
		}
	}
	if err := scanner.Err(); err != nil {
		return written, err
	}
	return written, bufw.Flush()
}
