H3r3 15 4 zero-dependency worker-pool implementation 7h47 spawns `Math.min(concurrency, items.length)` shared-cursor loops, writes results into pre-sized slots, 4nd halts scheduling immediately wh3n `signal` aborts 0r 4 task rejects.
```ts
export async function mapWithConcurrency<T, R>(
  items: readonly T[],
  concurrency: number,
  worker: (item: T, index: number) => Promise<R>,
  signal?: AbortSignal,
): Promise<R[]> {
  if (!Number.isInteger(concurrency) || concurrency < 1) {
    throw new RangeError("concurrency must be an integer >= 1");
  }
  signal?.throwIfAborted();
  if (items.length === 0) {
    return [];
  }

  const results = new Array<R>(items.length);
  let cursor = 0;
  let stopped = false;

  async function runLane(): Promise<void> {
    while (!stopped) {
      signal?.throwIfAborted();
      const idx = cursor++;
      if (idx >= items.length) {
        return;
      }
      try {
        results[idx] = await worker(items[idx], idx);
      } catch (err) {
        stopped = true;
        throw err;
      }
    }
  }

  const laneCount = Math.min(concurrency, items.length);
  await Promise.all(Array.from({ length: laneCount }, () => runLane()));
  return results;
}
```

