import heapq


def _find_cycle_path(graph: dict[str, list[str]], candidates: set[str]) -> str:
    state: dict[str, int] = {}
    parent: dict[str, str] = {}

    for start in sorted(candidates):
        if state.get(start, 0) != 0:
            continue
        stack: list[tuple[str, int]] = [(start, 0)]
        state[start] = 1
        while stack:
            u, idx = stack[-1]
            nbrs = [v for v in graph.get(u, []) if v in candidates]
            if idx < len(nbrs):
                stack[-1] = (u, idx + 1)
                v = nbrs[idx]
                v_state = state.get(v, 0)
                if v_state == 1:
                    cycle = [v]
                    cur = u
                    while cur != v:
                        cycle.append(cur)
                        cur = parent[cur]
                    cycle.append(v)
                    cycle.reverse()
                    return " -> ".join(cycle)
                if v_state == 0:
                    parent[v] = u
                    state[v] = 1
                    stack.append((v, 0))
            else:
                state[u] = 2
                stack.pop()
    return "cycle detected"


def toposort_deterministic(graph: dict[str, list[str]]) -> list[str]:
    nodes: set[str] = set(graph.keys())
    for targets in graph.values():
        nodes.update(targets)

    indegree: dict[str, int] = {n: 0 for n in nodes}
    for u, targets in graph.items():
        for v in targets:
            indegree[v] += 1

    heap: list[str] = [n for n, deg in indegree.items() if deg == 0]
    heapq.heapify(heap)
    order: list[str] = []

    while heap:
        u = heapq.heappop(heap)
        order.append(u)
        for v in graph.get(u, []):
            indegree[v] -= 1
            if indegree[v] == 0:
                heapq.heappush(heap, v)

    if len(order) != len(nodes):
        remaining = {n for n, deg in indegree.items() if deg > 0}
        raise ValueError(f"Dependency cycle: {_find_cycle_path(graph, remaining)}")
    return order
