```rust
use std::collections::HashMap;
use std::hash::Hash;

const NONE: usize = usize::MAX;

struct Node<K, V> {
    key: K,
    val: V,
    prev: usize,
    next: usize,
}

pub struct LruCache<K, V> {
    cap: usize,
    map: HashMap<K, usize>,
    nodes: Vec<Node<K, V>>,
    head: usize,
    tail: usize,
}

impl<K: Eq + Hash + Clone, V> LruCache<K, V> {
    pub fn new(capacity: usize) -> Self {
        assert!(capacity > 0, "capacity must be > 0");
        Self {
            cap: capacity,
            map: HashMap::with_capacity(capacity),
            nodes: Vec::with_capacity(capacity),
            head: NONE,
            tail: NONE,
        }
    }

    fn detach(&mut self, idx: usize) {
        let prev = self.nodes[idx].prev;
        let next = self.nodes[idx].next;
        if prev != NONE {
            self.nodes[prev].next = next;
        } else {
            self.head = next;
        }
        if next != NONE {
            self.nodes[next].prev = prev;
        } else {
            self.tail = prev;
        }
        self.nodes[idx].prev = NONE;
        self.nodes[idx].next = NONE;
    }

    fn attach_front(&mut self, idx: usize) {
        self.nodes[idx].prev = NONE;
        self.nodes[idx].next = self.head;
        if self.head != NONE {
            self.nodes[self.head].prev = idx;
        } else {
            self.tail = idx;
        }
        self.head = idx;
    }

    pub fn get(&mut self, key: &K) -> Option<&V> {
        let idx = *self.map.get(key)?;
        if idx != self.head {
            self.detach(idx);
            self.attach_front(idx);
        }
        Some(&self.nodes[idx].val)
    }

    pub fn put(&mut self, key: K, value: V) -> Option<V> {
        if let Some(&idx) = self.map.get(&key) {
            let old = std::mem::replace(&mut self.nodes[idx].val, value);
            if idx != self.head {
                self.detach(idx);
                self.attach_front(idx);
            }
            return Some(old);
        }
        if self.map.len() == self.cap {
            let evict_idx = self.tail;
            self.detach(evict_idx);
            let old_key = std::mem::replace(&mut self.nodes[evict_idx].key, key.clone());
            self.map.remove(&old_key);
            self.nodes[evict_idx].val = value;
            self.attach_front(evict_idx);
            self.map.insert(key, evict_idx);
        } else {
            let idx = self.nodes.len();
            self.nodes.push(Node {
                key: key.clone(),
                val: value,
                prev: NONE,
                next: NONE,
            });
            self.attach_front(idx);
            self.map.insert(key, idx);
        }
        None
    }
}
